package edu.klu.foodwaste.web;
import edu.klu.foodwaste.repo.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api") public class DashboardController{
 private final MealRepository meals;private final WasteRepository waste;private final UserRepository users;private final FeedbackRepository feedback;
 public DashboardController(MealRepository m,WasteRepository w,UserRepository u,FeedbackRepository f){meals=m;waste=w;users=u;feedback=f;}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){LocalDate today=LocalDate.now();var records=waste.findByRecordDateBetweenOrderByRecordDateDesc(today.withDayOfMonth(1),today);double prepared=records.stream().mapToDouble(x->x.getPreparedKg()).sum(),wasted=records.stream().mapToDouble(x->x.getWasteKg()).sum();double pct=prepared==0?0:Math.round(wasted/prepared*10000)/100.0;return Map.of("totalMeals",meals.count(),"totalUsers",users.count(),"mealsThisMonth",records.size(),"preparedKg",Math.round(prepared*100.0)/100.0,"wastedKg",Math.round(wasted*100.0)/100.0,"wastePercentage",pct,"feedbackCount",feedback.count(),"recentWaste",records.stream().limit(7).map(x->Map.of("date",x.getRecordDate().toString(),"mealName",x.getMeal().getName(),"wasteKg",x.getWasteKg(),"wastePercentage",x.getWastePercentage())).toList());}
 @GetMapping("/reports/summary") public Map<String,Object> summary(@RequestParam(defaultValue="month")String period){LocalDate end=LocalDate.now(),start=switch(period.toLowerCase()){case "day"->end;case "week"->end.minusDays(6);default->end.withDayOfMonth(1);};var r=waste.findByRecordDateBetweenOrderByRecordDateDesc(start,end);double p=r.stream().mapToDouble(x->x.getPreparedKg()).sum(),c=r.stream().mapToDouble(x->x.getConsumedKg()).sum(),w=r.stream().mapToDouble(x->x.getWasteKg()).sum();return Map.of("period",period,"from",start.toString(),"to",end.toString(),"recordCount",r.size(),"preparedKg",p,"consumedKg",c,"wastedKg",w,"wastePercentage",p==0?0:Math.round(w/p*10000)/100.0,"records",r.stream().map(x->Map.of("date",x.getRecordDate().toString(),"meal",x.getMeal().getName(),"preparedKg",x.getPreparedKg(),"consumedKg",x.getConsumedKg(),"wasteKg",x.getWasteKg(),"wastePercentage",x.getWastePercentage())).toList());}
}
